window.TOP20_SCOTUS = [{"id": "scotus-001", "case_name": "Citizens United v. Federal Election Commission", "docket": "08-205", "year": 2010, "argued": "2009-03-24", "decided": "2010-01-21", "holding_summary": "The government cannot ban corporations or unions from spending their own money to support or oppose political candidates, because that spending is protected speech under the First Amendment.", "majority_author": {"name": "Anthony Kennedy", "appointed_by": "Reagan", "party_of_president": "R"}, "vote": {"yes": 5, "no": 4}, "justices_for": [{"name": "Anthony Kennedy", "appointed_by": "Reagan", "party_of_president": "R", "lean": "conservative"}, {"name": "John Roberts", "appointed_by": "G.W. Bush", "party_of_president": "R", "lean": "conservative"}, {"name": "Antonin Scalia", "appointed_by": "Reagan", "party_of_president": "R", "lean": "conservative"}, {"name": "Samuel Alito", "appointed_by": "G.W. Bush", "party_of_president": "R", "lean": "conservative"}, {"name": "Clarence Thomas", "appointed_by": "G.H.W. Bush", "party_of_president": "R", "lean": "conservative"}], "justices_against": [{"name": "John Paul Stevens", "appointed_by": "Ford", "party_of_president": "R", "lean": "liberal"}, {"name": "Ruth Bader Ginsburg", "appointed_by": "Clinton", "party_of_president": "D", "lean": "liberal"}, {"name": "Stephen Breyer", "appointed_by": "Clinton", "party_of_president": "D", "lean": "liberal"}, {"name": "Sonia Sotomayor", "appointed_by": "Obama", "party_of_president": "D", "lean": "liberal"}], "lean_breakdown": {"conservative": 5, "liberal": 4}, "impact_summary": "Opened unlimited corporate and union spending in elections, leading to billions in outside money and the rise of super PACs that can raise and spend without limits.", "impact_numbers": [{"metric": "Outside spending in 2014 vs 2010", "value": "$486 million in 2014 vs $220 million in 2010 (inflation-adjusted)", "source_url": "https://www.brennancenter.org/our-work/research-reports/citizens-united-explained", "source_name": "Brennan Center"}, {"metric": "Super PAC spending since 2010", "value": "Over $1 billion; 195 individuals and spouses gave roughly 60% of that total", "source_url": "https://www.brennancenter.org/our-work/research-reports/citizens-united-explained", "source_name": "Brennan Center"}], "demographics_hit": ["All voters", "Low-income communities"], "impact_on_you": "This decision lets wealthy individuals and corporations spend unlimited money to influence elections, which can drown out the voices of regular voters.", "category": "Campaign Finance & Democracy", "tags": ["dark money", "corporate speech", "super PACs"], "constitutional_question": "Does a law that stops corporations and unions from spending their own money on election ads violate the First Amendment's guarantee of free speech?", "key_dissent_quote": "While American democracy is imperfect, few outside the majority of this Court would have thought its flaws included a dearth of corporate money in politics.", "sources": [{"url": "https://www.oyez.org/cases/2008/08-205", "title": "Oyez: Citizens United v. FEC", "excerpt": "Full case data including vote breakdown, argued/decided dates, and docket number", "tier": "A"}, {"url": "https://www.brennancenter.org/our-work/research-reports/citizens-united-explained", "title": "Brennan Center: Outside Spending Since Citizens United", "excerpt": "$486M in 2014 outside spending and $1B+ super PAC spending since 2010", "tier": "A"}]}, {"id": "scotus-002", "case_name": "Shelby County v. Holder", "docket": "12-96", "year": 2013, "argued": "2013-02-27", "decided": "2013-06-25", "holding_summary": "The formula used to decide which states need federal approval before changing their voting laws is outdated and unconstitutional, effectively ending the preclearance requirement of the Voting Rights Act.", "majority_author": {"name": "John Roberts", "appointed_by": "G.W. Bush", "party_of_president": "R"}, "vote": {"yes": 5, "no": 4}, "justices_for": [{"name": "John Roberts", "appointed_by": "G.W. Bush", "party_of_president": "R", "lean": "conservative"}, {"name": "Antonin Scalia", "appointed_by": "Reagan", "party_of_president": "R", "lean": "conservative"}, {"name": "Anthony Kennedy", "appointed_by": "Reagan", "party_of_president": "R", "lean": "conservative"}, {"name": "Clarence Thomas", "appointed_by": "G.H.W. Bush", "party_of_president": "R", "lean": "conservative"}, {"name": "Samuel Alito", "appointed_by": "G.W. Bush", "party_of_president": "R", "lean": "conservative"}], "justices_against": [{"name": "Ruth Bader Ginsburg", "appointed_by": "Clinton", "party_of_president": "D", "lean": "liberal"}, {"name": "Stephen Breyer", "appointed_by": "Clinton", "party_of_president": "D", "lean": "liberal"}, {"name": "Sonia Sotomayor", "appointed_by": "Obama", "party_of_president": "D", "lean": "liberal"}, {"name": "Elena Kagan", "appointed_by": "Obama", "party_of_president": "D", "lean": "liberal"}], "lean_breakdown": {"conservative": 5, "liberal": 4}, "impact_summary": "Removed federal oversight of voting changes in states with histories of racial discrimination, leading to new restrictive voting laws and massive voter roll purges.", "impact_numbers": [{"metric": "Extra voters purged in formerly-covered jurisdictions in first post-Shelby cycle", "value": "Approximately 363,000 more voters removed from rolls", "source_url": "https://www.brennancenter.org/our-work/research-reports/purges-growing-threat-right-vote", "source_name": "Brennan Center: Purges: A Growing Threat (2018)"}, {"metric": "Voter purges if formerly-covered jurisdictions matched uncovered jurisdictions", "value": "2 million fewer purges would have occurred", "source_url": "https://www.brennancenter.org/our-work/research-reports/purges-growing-threat-right-vote", "source_name": "Brennan Center: Purges: A Growing Threat (2018)"}], "demographics_hit": ["Communities of color", "Low-income communities", "Southern states"], "impact_on_you": "This decision made it easier for states to pass laws that can make it harder for you to vote, like reducing polling places in your neighborhood or purging your name from voter rolls.", "category": "Campaign Finance & Democracy", "tags": ["voting rights", "racial discrimination", "preclearance"], "constitutional_question": "Is the formula in the Voting Rights Act that determines which states need federal approval before changing their voting laws still valid under the Constitution, given how much the country has changed since 1965?", "key_dissent_quote": "Throwing out preclearance when it has worked and is continuing to work to stop discriminatory changes is like throwing away your umbrella in a rainstorm because you are not getting wet.", "sources": [{"url": "https://www.oyez.org/cases/2012/12-96", "title": "Oyez: Shelby County v. Holder", "excerpt": "Full case data including vote, argued/decided dates, and party breakdown", "tier": "A"}, {"url": "https://www.brennancenter.org/our-work/research-reports/purges-growing-threat-right-vote", "title": "Brennan Center: Purges: A Growing Threat (2018)", "excerpt": "363,000 extra voters purged; 2M fewer purges if rates matched uncovered jurisdictions", "tier": "A"}]}, {"id": "scotus-003", "case_name": "Rucho v. Common Cause", "docket": "18-422", "year": 2019, "argued": "2019-03-26", "decided": "2019-06-27", "holding_summary": "Federal courts cannot hear cases about partisan gerrymandering because those claims are political questions that courts cannot resolve.", "majority_author": {"name": "John Roberts", "appointed_by": "G.W. Bush", "party_of_president": "R"}, "vote": {"yes": 5, "no": 4}, "justices_for": [{"name": "John Roberts", "appointed_by": "G.W. Bush", "party_of_president": "R", "lean": "conservative"}, {"name": "Clarence Thomas", "appointed_by": "G.H.W. Bush", "party_of_president": "R", "lean": "conservative"}, {"name": "Samuel Alito", "appointed_by": "G.W. Bush", "party_of_president": "R", "lean": "conservative"}, {"name": "Neil Gorsuch", "appointed_by": "Trump", "party_of_president": "R", "lean": "conservative"}, {"name": "Brett Kavanaugh", "appointed_by": "Trump", "party_of_president": "R", "lean": "conservative"}], "justices_against": [{"name": "Elena Kagan", "appointed_by": "Obama", "party_of_president": "D", "lean": "liberal"}, {"name": "Ruth Bader Ginsburg", "appointed_by": "Clinton", "party_of_president": "D", "lean": "liberal"}, {"name": "Stephen Breyer", "appointed_by": "Clinton", "party_of_president": "D", "lean": "liberal"}, {"name": "Sonia Sotomayor", "appointed_by": "Obama", "party_of_president": "D", "lean": "liberal"}], "lean_breakdown": {"conservative": 5, "liberal": 4}, "impact_summary": "Made it impossible to challenge rigged voting maps in federal court, allowing politicians to pick their voters instead of voters picking their politicians.", "impact_numbers": [{"metric": "North Carolina 2018 House \u2014 Republican vote share vs seats won", "value": "R=50.3% of votes but won 10 of 13 seats (77%); D=48.4% of votes but won only 3 of 13 (23%)", "source_url": "https://www.supremecourt.gov/DocketPDF/18/18-422/81896/20190104151102480_No.%2018-422%20Supp%20Br%20Common%20Cause%20Appellees.pdf", "source_name": "SCOTUS docket, Supplemental Brief of Common Cause Appellees, No. 18-422"}], "demographics_hit": ["All voters", "Communities of color"], "impact_on_you": "This decision means that even if you can prove your voting map was drawn to cheat you out of fair representation, federal courts cannot help you.", "category": "Campaign Finance & Democracy", "tags": ["gerrymandering", "voting maps", "political question"], "constitutional_question": "Can federal courts hear cases that challenge voting maps drawn to give one political party an extreme and unfair advantage?", "key_dissent_quote": "The majority concedes (really, how could it not?) that gerrymandering is 'incompatible with democratic principles.' And therefore what? That recognition would seem to demand a response.", "sources": [{"url": "https://www.oyez.org/cases/2018/18-422", "title": "Oyez: Rucho v. Common Cause", "excerpt": "Full case data with vote breakdown, argued/decided dates", "tier": "A"}, {"url": "https://www.supremecourt.gov/DocketPDF/18/18-422/81896/20190104151102480_No.%2018-422%20Supp%20Br%20Common%20Cause%20Appellees.pdf", "title": "SCOTUS docket: Supplemental Brief of Common Cause Appellees", "excerpt": "NC 2018: R 50.3% -> 10/13 seats, D 48.4% -> 3/13 seats", "tier": "A"}]}, {"id": "scotus-004", "case_name": "Bush v. Gore", "docket": "00-949", "year": 2000, "argued": "2000-12-11", "decided": "2000-12-12", "holding_summary": "The Florida Supreme Court's order for a statewide manual recount of votes in the 2000 presidential election violated the Equal Protection Clause because there was no uniform standard for counting votes, effectively deciding the election.", "majority_author": {"name": "William Rehnquist", "appointed_by": "Reagan", "party_of_president": "R"}, "vote": {"yes": 5, "no": 4}, "justices_for": [{"name": "William Rehnquist", "appointed_by": "Reagan", "party_of_president": "R", "lean": "conservative"}, {"name": "Sandra Day O'Connor", "appointed_by": "Reagan", "party_of_president": "R", "lean": "conservative"}, {"name": "Antonin Scalia", "appointed_by": "Reagan", "party_of_president": "R", "lean": "conservative"}, {"name": "Anthony Kennedy", "appointed_by": "Reagan", "party_of_president": "R", "lean": "conservative"}, {"name": "Clarence Thomas", "appointed_by": "G.H.W. Bush", "party_of_president": "R", "lean": "conservative"}], "justices_against": [{"name": "John Paul Stevens", "appointed_by": "Ford", "party_of_president": "R", "lean": "liberal"}, {"name": "David Souter", "appointed_by": "G.H.W. Bush", "party_of_president": "R", "lean": "liberal"}, {"name": "Ruth Bader Ginsburg", "appointed_by": "Clinton", "party_of_president": "D", "lean": "liberal"}, {"name": "Stephen Breyer", "appointed_by": "Clinton", "party_of_president": "D", "lean": "liberal"}], "lean_breakdown": {"conservative": 5, "liberal": 4}, "impact_summary": "The Supreme Court halted a recount and effectively decided the 2000 presidential election, with Black voters suffering disproportionately high ballot rejection rates.", "impact_numbers": [{"metric": "Spoiled ballots in Florida 2000", "value": "Approximately 180,000 ballots rejected", "source_url": "https://www.usccr.gov/pubs/vote2000/report/main.htm", "source_name": "U.S. Commission on Civil Rights: Voting Irregularities in Florida"}, {"metric": "Black voters' ballot rejection rate vs non-Black", "value": "Black voters 11% of electorate but ~54% of spoiled ballots; 14.4% rejection vs 1.6% non-Black", "source_url": "https://www.usccr.gov/pubs/vote2000/report/main.htm", "source_name": "U.S. Commission on Civil Rights: Voting Irregularities in Florida"}], "demographics_hit": ["Communities of color", "Low-income communities"], "impact_on_you": "This decision showed that the Supreme Court can step into a presidential election and stop vote counting, and that your ballot is more likely to be thrown out if you live in certain communities.", "category": "Campaign Finance & Democracy", "tags": ["presidential election", "recount", "Equal Protection"], "constitutional_question": "Does the Constitution require a statewide recount to use the same ballot-counting standard everywhere, and was there time to set one up before the deadline for choosing electors?", "key_dissent_quote": "Although we may never know with complete certainty the identity of the winner of this year's Presidential election, the identity of the loser is perfectly clear. It is the Nation's confidence in the judge as an impartial guardian of the rule of law.", "sources": [{"url": "https://www.oyez.org/cases/2000/00-949", "title": "Oyez: Bush v. Gore", "excerpt": "Full case data including vote breakdown, argued/decided dates, per-justice votes", "tier": "A"}, {"url": "https://www.usccr.gov/pubs/vote2000/report/main.htm", "title": "U.S. Commission on Civil Rights: Voting Irregularities in Florida", "excerpt": "180,000 spoiled ballots; Black voters 11% of electorate but ~54% of spoiled ballots", "tier": "A"}]}, {"id": "scotus-005", "case_name": "Husted v. A. Philip Randolph Institute", "docket": "16-980", "year": 2018, "argued": "2018-01-10", "decided": "2018-06-11", "holding_summary": "States can remove people from voter rolls if they skip a few elections and fail to return a mailed notice, even though federal law was designed to protect voters from being purged just for not voting.", "majority_author": {"name": "Samuel Alito", "appointed_by": "G.W. Bush", "party_of_president": "R"}, "vote": {"yes": 5, "no": 4}, "justices_for": [{"name": "Samuel Alito", "appointed_by": "G.W. Bush", "party_of_president": "R", "lean": "conservative"}, {"name": "John Roberts", "appointed_by": "G.W. Bush", "party_of_president": "R", "lean": "conservative"}, {"name": "Anthony Kennedy", "appointed_by": "Reagan", "party_of_president": "R", "lean": "conservative"}, {"name": "Clarence Thomas", "appointed_by": "G.H.W. Bush", "party_of_president": "R", "lean": "conservative"}, {"name": "Neil Gorsuch", "appointed_by": "Trump", "party_of_president": "R", "lean": "conservative"}], "justices_against": [{"name": "Stephen Breyer", "appointed_by": "Clinton", "party_of_president": "D", "lean": "liberal"}, {"name": "Ruth Bader Ginsburg", "appointed_by": "Clinton", "party_of_president": "D", "lean": "liberal"}, {"name": "Sonia Sotomayor", "appointed_by": "Obama", "party_of_president": "D", "lean": "liberal"}, {"name": "Elena Kagan", "appointed_by": "Obama", "party_of_president": "D", "lean": "liberal"}], "lean_breakdown": {"conservative": 5, "liberal": 4}, "impact_summary": "Made it easier for states to purge eligible voters from the rolls, with millions of Americans removed nationwide and error rates exceeding 15% in some states.", "impact_numbers": [{"metric": "Total voter registrations removed nationally 2014-2016", "value": "16,696,470 registrants removed", "source_url": "https://www.eac.gov/research-and-data/datasets-codebooks-and-surveys", "source_name": "EAC EAVS 2016"}, {"metric": "Ohio 2019 purge list error rate", "value": "~235,000 names on purge list with ~40,000 errors (over 15% error rate)", "source_url": "https://www.supremecourt.gov/DocketPDF/19/19-1257/154461/20200918142917601_2020-09-17.pdf", "source_name": "SCOTUS DocketPDF 19-1257, amicus brief"}], "demographics_hit": ["Low-income communities", "Communities of color", "Young voters"], "impact_on_you": "If you skip a couple of elections, your state can remove you from the voter rolls without ever talking to you, and you might not find out until you show up to vote and are turned away.", "category": "Campaign Finance & Democracy", "tags": ["voter purges", "NVRA", "Ohio"], "constitutional_question": "Does federal law allow a state to remove people from its voter rolls just because they chose not to vote in a few elections and did not return a mailed notice?", "key_dissent_quote": "The Court today upholds a program that targets a group of people who are not more likely to have moved \u2014 and who, it turns out, have done nothing other than fail to cast a ballot.", "sources": [{"url": "https://www.oyez.org/cases/2017/16-980", "title": "Oyez: Husted v. A. Philip Randolph Institute", "excerpt": "5-4 decision, argued Jan 2018, decided Jun 2018", "tier": "A"}, {"url": "https://www.eac.gov/research-and-data/datasets-codebooks-and-surveys", "title": "EAC EAVS 2016", "excerpt": "16,696,470 registrants removed nationally 2014-2016", "tier": "A"}]}, {"id": "scotus-006", "case_name": "Parents Involved in Community Schools v. Seattle School District No. 1", "docket": "05-908", "year": 2007, "argued": "2006-12-04", "decided": "2007-06-28", "holding_summary": "Public school districts cannot use a student's race as a deciding factor when assigning students to schools, even when the goal is to keep schools racially diverse.", "majority_author": {"name": "John Roberts", "appointed_by": "G.W. Bush", "party_of_president": "R"}, "vote": {"yes": 5, "no": 4}, "justices_for": [{"name": "John Roberts", "appointed_by": "G.W. Bush", "party_of_president": "R", "lean": "conservative"}, {"name": "Antonin Scalia", "appointed_by": "Reagan", "party_of_president": "R", "lean": "conservative"}, {"name": "Anthony Kennedy", "appointed_by": "Reagan", "party_of_president": "R", "lean": "conservative"}, {"name": "Clarence Thomas", "appointed_by": "G.H.W. Bush", "party_of_president": "R", "lean": "conservative"}, {"name": "Samuel Alito", "appointed_by": "G.W. Bush", "party_of_president": "R", "lean": "conservative"}], "justices_against": [{"name": "Stephen Breyer", "appointed_by": "Clinton", "party_of_president": "D", "lean": "liberal"}, {"name": "John Paul Stevens", "appointed_by": "Ford", "party_of_president": "R", "lean": "liberal"}, {"name": "David Souter", "appointed_by": "G.H.W. Bush", "party_of_president": "R", "lean": "liberal"}, {"name": "Ruth Bader Ginsburg", "appointed_by": "Clinton", "party_of_president": "D", "lean": "liberal"}], "lean_breakdown": {"conservative": 5, "liberal": 4}, "impact_summary": "Stripped school districts of a tool to voluntarily desegregate, contributing to resegregation \u2014 today over one-third of U.S. students attend schools that are 75% or more single-race.", "impact_numbers": [{"metric": "Students in 75%+ single-race schools (2020-21)", "value": "18.5 million students (over one-third); 14% attend schools 90%+ single-race", "source_url": "https://www.gao.gov/assets/gao-22-104737.pdf", "source_name": "GAO-22-104737"}], "demographics_hit": ["Communities of color", "Students", "Low-income communities"], "impact_on_you": "This decision limits how school districts can create diverse classrooms, which means more students attend racially isolated schools that often have fewer resources and opportunities.", "category": "Civil Rights & Equal Protection", "tags": ["school segregation", "affirmative action", "Equal Protection"], "constitutional_question": "Can public school districts voluntarily use a student's race as one factor in school assignments to achieve racial diversity?", "key_dissent_quote": "The last half-century has witnessed great strides toward racial equality, but we have not yet realized the promise of Brown. To invalidate the plans under review is to threaten the promise of Brown.", "sources": [{"url": "https://www.oyez.org/cases/2006/05-908", "title": "Oyez: Parents Involved v. Seattle School District No. 1", "excerpt": "5-4 decision, Roberts authored the plurality opinion", "tier": "A"}, {"url": "https://www.gao.gov/assets/gao-22-104737.pdf", "title": "GAO-22-104737", "excerpt": "18.5M students in 75%+ single-race schools; 14% in 90%+", "tier": "A"}]}, {"id": "scotus-007", "case_name": "Ledbetter v. Goodyear Tire & Rubber Co.", "docket": "05-1074", "year": 2007, "argued": "2006-11-27", "decided": "2007-05-29", "holding_summary": "A worker must file a pay discrimination claim within 180 days of the first discriminatory paycheck, even if she did not discover the pay gap until years later.", "majority_author": {"name": "Samuel Alito", "appointed_by": "G.W. Bush", "party_of_president": "R"}, "vote": {"yes": 5, "no": 4}, "justices_for": [{"name": "Samuel Alito", "appointed_by": "G.W. Bush", "party_of_president": "R", "lean": "conservative"}, {"name": "John Roberts", "appointed_by": "G.W. Bush", "party_of_president": "R", "lean": "conservative"}, {"name": "Antonin Scalia", "appointed_by": "Reagan", "party_of_president": "R", "lean": "conservative"}, {"name": "Anthony Kennedy", "appointed_by": "Reagan", "party_of_president": "R", "lean": "conservative"}, {"name": "Clarence Thomas", "appointed_by": "G.H.W. Bush", "party_of_president": "R", "lean": "conservative"}], "justices_against": [{"name": "Ruth Bader Ginsburg", "appointed_by": "Clinton", "party_of_president": "D", "lean": "liberal"}, {"name": "John Paul Stevens", "appointed_by": "Ford", "party_of_president": "R", "lean": "liberal"}, {"name": "David Souter", "appointed_by": "G.H.W. Bush", "party_of_president": "R", "lean": "liberal"}, {"name": "Stephen Breyer", "appointed_by": "Clinton", "party_of_president": "D", "lean": "liberal"}], "lean_breakdown": {"conservative": 5, "liberal": 4}, "impact_summary": "Cut off pay discrimination lawsuits before many workers could even learn they were being underpaid, reducing Lily Ledbetter's jury award from over $3.5 million to just $360,000.", "impact_numbers": [{"metric": "Ledbetter's jury award reduction", "value": "$3.5+ million jury award reduced to $360,000 by ruling", "source_url": "https://www.oyez.org/cases/2006/05-1074", "source_name": "Oyez: Ledbetter v. Goodyear"}, {"metric": "Female-to-male earnings ratio (2007)", "value": "Women earned 78 cents for every dollar men earned", "source_url": "https://www.census.gov/library/publications/2008/demo/p60-235.html", "source_name": "Census P60-235"}], "demographics_hit": ["Women", "Low-income communities"], "impact_on_you": "If your employer quietly pays you less than your coworkers because of your gender or race, this decision can block you from suing unless you catch it almost immediately, even though most people don't find out for years.", "category": "Civil Rights & Equal Protection", "tags": ["pay discrimination", "equal pay", "Title VII"], "constitutional_question": "Does the 180-day deadline for filing a pay discrimination claim start when the employer first decides to pay someone less, or with each new discriminatory paycheck?", "key_dissent_quote": "The Court's insistence on immediate contest overlooks common characteristics of pay discrimination. A pay-setting decision often occurs in small increments; only over time is there strong cause to suspect that discrimination is at work.", "sources": [{"url": "https://www.oyez.org/cases/2006/05-1074", "title": "Oyez: Ledbetter v. Goodyear", "excerpt": "5-4 decision, Alito authored; $3.5M+ award reduced to $360,000", "tier": "A"}, {"url": "https://www.census.gov/library/publications/2008/demo/p60-235.html", "title": "Census P60-235", "excerpt": "Female-to-male earnings ratio 0.78 in 2007", "tier": "A"}]}, {"id": "scotus-008", "case_name": "Ashcroft v. Iqbal", "docket": "07-1015", "year": 2009, "argued": "2008-12-10", "decided": "2009-05-18", "holding_summary": "To sue high-ranking government officials for unconstitutional conduct, a plaintiff must show specific facts that make it plausible the officials personally ordered the violation \u2014 a vague accusation is not enough to get past the courthouse door.", "majority_author": {"name": "Anthony Kennedy", "appointed_by": "Reagan", "party_of_president": "R"}, "vote": {"yes": 5, "no": 4}, "justices_for": [{"name": "Anthony Kennedy", "appointed_by": "Reagan", "party_of_president": "R", "lean": "conservative"}, {"name": "John Roberts", "appointed_by": "G.W. Bush", "party_of_president": "R", "lean": "conservative"}, {"name": "Antonin Scalia", "appointed_by": "Reagan", "party_of_president": "R", "lean": "conservative"}, {"name": "Clarence Thomas", "appointed_by": "G.H.W. Bush", "party_of_president": "R", "lean": "conservative"}, {"name": "Samuel Alito", "appointed_by": "G.W. Bush", "party_of_president": "R", "lean": "conservative"}], "justices_against": [{"name": "David Souter", "appointed_by": "G.H.W. Bush", "party_of_president": "R", "lean": "liberal"}, {"name": "John Paul Stevens", "appointed_by": "Ford", "party_of_president": "R", "lean": "liberal"}, {"name": "Ruth Bader Ginsburg", "appointed_by": "Clinton", "party_of_president": "D", "lean": "liberal"}, {"name": "Stephen Breyer", "appointed_by": "Clinton", "party_of_president": "D", "lean": "liberal"}], "lean_breakdown": {"conservative": 5, "liberal": 4}, "impact_summary": "Made it much harder for civil rights plaintiffs to get their day in court by raising the bar for what must be in a complaint, leading to a significant jump in dismissals of civil rights cases.", "impact_numbers": [{"metric": "Civil rights employment case dismissal rate increase", "value": "Dismissals rose from 27.8% before the ruling to 35.2% after", "source_url": "https://www.fjc.gov/sites/default/files/2012/IqbalReport.pdf", "source_name": "FJC Iqbal Report (Civin & Adegbile, NAACP LDF brief)"}, {"metric": "Other civil rights case dismissal rate increase", "value": "Dismissals rose from 25.9% to 36.9%", "source_url": "https://www.fjc.gov/sites/default/files/2012/IqbalReport.pdf", "source_name": "FJC Iqbal Report"}], "demographics_hit": ["Communities of color", "Low-income communities", "Immigrants"], "impact_on_you": "If the government violates your rights, this decision makes it much harder to even get your case heard in court because you must prove your case at the very start, before you can gather evidence through the legal process.", "category": "Civil Rights & Equal Protection", "tags": ["pleading standard", "civil procedure", "qualified immunity"], "constitutional_question": "How much specific detail must a person include when filing a lawsuit against high-ranking government officials, before they can proceed to gather evidence?", "key_dissent_quote": "The majority's approach converts the pleading standard from a gateway into a barrier that will prevent many valid civil rights claims from ever being heard.", "sources": [{"url": "https://www.oyez.org/cases/2008/07-1015", "title": "Oyez: Ashcroft v. Iqbal", "excerpt": "5-4 decision, Kennedy authored; argued Dec 2008, decided May 2009", "tier": "A"}, {"url": "https://www.fjc.gov/sites/default/files/2012/IqbalReport.pdf", "title": "FJC Iqbal Report", "excerpt": "Civil rights employment dismissals 27.8% to 35.2%; other civil rights 25.9% to 36.9%", "tier": "A"}]}, {"id": "scotus-009", "case_name": "United States v. Morrison", "docket": "99-5", "year": 2000, "argued": "2000-01-11", "decided": "2000-05-15", "holding_summary": "Congress cannot use its power to regulate interstate commerce to give victims of gender-based violence the right to sue their attackers in federal court, striking down part of the Violence Against Women Act.", "majority_author": {"name": "William Rehnquist", "appointed_by": "Reagan", "party_of_president": "R"}, "vote": {"yes": 5, "no": 4}, "justices_for": [{"name": "William Rehnquist", "appointed_by": "Reagan", "party_of_president": "R", "lean": "conservative"}, {"name": "Sandra Day O'Connor", "appointed_by": "Reagan", "party_of_president": "R", "lean": "conservative"}, {"name": "Antonin Scalia", "appointed_by": "Reagan", "party_of_president": "R", "lean": "conservative"}, {"name": "Anthony Kennedy", "appointed_by": "Reagan", "party_of_president": "R", "lean": "conservative"}, {"name": "Clarence Thomas", "appointed_by": "G.H.W. Bush", "party_of_president": "R", "lean": "conservative"}], "justices_against": [{"name": "Stephen Breyer", "appointed_by": "Clinton", "party_of_president": "D", "lean": "liberal"}, {"name": "John Paul Stevens", "appointed_by": "Ford", "party_of_president": "R", "lean": "liberal"}, {"name": "David Souter", "appointed_by": "G.H.W. Bush", "party_of_president": "R", "lean": "liberal"}, {"name": "Ruth Bader Ginsburg", "appointed_by": "Clinton", "party_of_president": "D", "lean": "liberal"}], "lean_breakdown": {"conservative": 5, "liberal": 4}, "impact_summary": "Stripped victims of gender-based violence of the right to sue in federal court, leaving them to navigate a patchwork of state courts with widely varying protections.", "impact_numbers": [{"metric": "Intimate partner violence victims who are female", "value": "85% of intimate partner violence victims are women", "source_url": "https://bjs.ojp.gov/content/pub/pdf/ipv9310.pdf", "source_name": "BJS: Intimate Partner Violence, 1993-2010"}], "demographics_hit": ["Women", "Domestic violence survivors"], "impact_on_you": "If you are a victim of gender-based violence, this decision took away your right to seek justice in federal court, forcing you to rely on your state's laws and courts, which may offer less protection.", "category": "Civil Rights & Equal Protection", "tags": ["domestic violence", "Commerce Clause", "VAWA"], "constitutional_question": "Can Congress use its power to regulate interstate commerce to allow victims of gender-based violence to sue their attackers in federal court?", "key_dissent_quote": "The Court's opinion today holds that Congress cannot provide a federal remedy for the victims of gender-motivated violence \u2014 even though that violence, considered in the aggregate, has a substantial effect on interstate commerce.", "sources": [{"url": "https://www.oyez.org/cases/1999/99-5", "title": "Oyez: United States v. Morrison", "excerpt": "5-4 decision, Rehnquist authored; argued Jan 2000, decided May 2000", "tier": "A"}, {"url": "https://bjs.ojp.gov/content/pub/pdf/ipv9310.pdf", "title": "BJS: Intimate Partner Violence, 1993-2010", "excerpt": "85% of IPV victims are female", "tier": "A"}]}, {"id": "scotus-010", "case_name": "Castle Rock v. Gonzales", "docket": "04-278", "year": 2005, "argued": "2005-03-21", "decided": "2005-06-27", "holding_summary": "A person does not have a constitutional right to have police enforce a restraining order, even when the police know the order exists and the person protected by it is in danger.", "majority_author": {"name": "Antonin Scalia", "appointed_by": "Reagan", "party_of_president": "R"}, "vote": {"yes": 7, "no": 2}, "justices_for": [{"name": "Antonin Scalia", "appointed_by": "Reagan", "party_of_president": "R", "lean": "conservative"}, {"name": "William Rehnquist", "appointed_by": "Reagan", "party_of_president": "R", "lean": "conservative"}, {"name": "Sandra Day O'Connor", "appointed_by": "Reagan", "party_of_president": "R", "lean": "conservative"}, {"name": "Anthony Kennedy", "appointed_by": "Reagan", "party_of_president": "R", "lean": "conservative"}, {"name": "Clarence Thomas", "appointed_by": "G.H.W. Bush", "party_of_president": "R", "lean": "conservative"}, {"name": "Stephen Breyer", "appointed_by": "Clinton", "party_of_president": "D", "lean": "liberal"}, {"name": "David Souter", "appointed_by": "G.H.W. Bush", "party_of_president": "R", "lean": "liberal"}], "justices_against": [{"name": "John Paul Stevens", "appointed_by": "Ford", "party_of_president": "R", "lean": "liberal"}, {"name": "Ruth Bader Ginsburg", "appointed_by": "Clinton", "party_of_president": "D", "lean": "liberal"}], "lean_breakdown": {"conservative": 5, "liberal": 2}, "impact_summary": "Ruled that police have no constitutional duty to enforce restraining orders, leaving domestic violence victims without legal recourse when police fail to act on known threats.", "impact_numbers": [{"metric": "Protective order violation rate", "value": "50% of protective order participants reported the order was violated", "source_url": "https://www.ojp.gov/pdffiles1/nij/grants/224337.pdf", "source_name": "NIJ: Kentucky Civil Protective Order Study"}], "demographics_hit": ["Women", "Domestic violence survivors", "Children"], "impact_on_you": "If you have a court-issued protection order against someone threatening you, the police have no constitutional duty to enforce it \u2014 and if they fail to protect you, you cannot sue them.", "category": "Civil Rights & Equal Protection", "tags": ["domestic violence", "due process", "police enforcement"], "constitutional_question": "Does the Constitution require police to enforce a restraining order when the person protected by it is in danger?", "key_dissent_quote": "The Court holds that the police had no duty to enforce a restraining order even when they knew it existed and had acknowledged the danger. That holding profoundly misreads the Due Process Clause.", "sources": [{"url": "https://www.oyez.org/cases/2004/04-278", "title": "Oyez: Castle Rock v. Gonzales", "excerpt": "7-2 decision, Scalia authored; argued Mar 2005, decided Jun 2005", "tier": "A"}, {"url": "https://www.ojp.gov/pdffiles1/nij/grants/224337.pdf", "title": "NIJ: Kentucky Civil Protective Order Study", "excerpt": "50% of participants reported the order was violated", "tier": "A"}]}, {"id": "scotus-011", "case_name": "Janus v. American Federation of State, County, and Municipal Employees, Council 31", "docket": "16-1466", "year": 2018, "argued": "2018-02-26", "decided": "2018-06-27", "holding_summary": "Public-sector unions cannot require non-members to pay fees that cover the cost of collective bargaining, because forcing someone to fund political speech they disagree with violates the First Amendment.", "majority_author": {"name": "Samuel Alito", "appointed_by": "G.W. Bush", "party_of_president": "R"}, "vote": {"yes": 5, "no": 4}, "justices_for": [{"name": "Samuel Alito", "appointed_by": "G.W. Bush", "party_of_president": "R", "lean": "conservative"}, {"name": "John Roberts", "appointed_by": "G.W. Bush", "party_of_president": "R", "lean": "conservative"}, {"name": "Anthony Kennedy", "appointed_by": "Reagan", "party_of_president": "R", "lean": "conservative"}, {"name": "Clarence Thomas", "appointed_by": "G.H.W. Bush", "party_of_president": "R", "lean": "conservative"}, {"name": "Neil Gorsuch", "appointed_by": "Trump", "party_of_president": "R", "lean": "conservative"}], "justices_against": [{"name": "Elena Kagan", "appointed_by": "Obama", "party_of_president": "D", "lean": "liberal"}, {"name": "Ruth Bader Ginsburg", "appointed_by": "Clinton", "party_of_president": "D", "lean": "liberal"}, {"name": "Stephen Breyer", "appointed_by": "Clinton", "party_of_president": "D", "lean": "liberal"}, {"name": "Sonia Sotomayor", "appointed_by": "Obama", "party_of_president": "D", "lean": "liberal"}], "lean_breakdown": {"conservative": 5, "liberal": 4}, "impact_summary": "Weakened public-sector unions by eliminating their main funding source, leading to an immediate drop in union membership and reduced bargaining power for teachers, firefighters, nurses, and other public workers.", "impact_numbers": [{"metric": "Public-sector union density drop after Janus", "value": "34.4% in 2017 to 33.9% in 2018; membership fell from 7,216,000 to 7,167,000", "source_url": "https://www.bls.gov/news.release/archives/union2_01182019.pdf", "source_name": "BLS Union Members 2018"}], "demographics_hit": ["Public-sector workers", "Women", "Communities of color", "Teachers"], "impact_on_you": "If you work as a teacher, firefighter, nurse, or any public employee, this decision makes it harder for your union to negotiate for better pay and working conditions by allowing coworkers to get the benefits of union negotiation without contributing to its costs.", "category": "Labor, Consumer & Corporate Power", "tags": ["unions", "First Amendment", "public sector"], "constitutional_question": "Can a state require public employees who choose not to join a union to pay fees that cover the cost of collective bargaining that benefits everyone?", "key_dissent_quote": "The majority is turning the First Amendment into a sword, and using it against workaday economic policy.", "sources": [{"url": "https://www.oyez.org/cases/2017/16-1466", "title": "Oyez: Janus v. AFSCME", "excerpt": "5-4 decision, Alito authored; argued Feb 2018, decided Jun 2018", "tier": "A"}, {"url": "https://www.bls.gov/news.release/archives/union2_01182019.pdf", "title": "BLS Union Members 2018", "excerpt": "Public-sector union density 34.4% to 33.9%; membership 7,216k to 7,167k", "tier": "A"}]}, {"id": "scotus-012", "case_name": "AT&T Mobility LLC v. Concepcion", "docket": "09-893", "year": 2011, "argued": "2010-11-09", "decided": "2011-04-27", "holding_summary": "Companies can use the fine print in consumer contracts to block customers from joining together in class-action lawsuits, forcing each person to fight the company alone in arbitration even when the company wronged millions of people in the same way.", "majority_author": {"name": "Antonin Scalia", "appointed_by": "Reagan", "party_of_president": "R"}, "vote": {"yes": 5, "no": 4}, "justices_for": [{"name": "Antonin Scalia", "appointed_by": "Reagan", "party_of_president": "R", "lean": "conservative"}, {"name": "John Roberts", "appointed_by": "G.W. Bush", "party_of_president": "R", "lean": "conservative"}, {"name": "Anthony Kennedy", "appointed_by": "Reagan", "party_of_president": "R", "lean": "conservative"}, {"name": "Clarence Thomas", "appointed_by": "G.H.W. Bush", "party_of_president": "R", "lean": "conservative"}, {"name": "Samuel Alito", "appointed_by": "G.W. Bush", "party_of_president": "R", "lean": "conservative"}], "justices_against": [{"name": "Stephen Breyer", "appointed_by": "Clinton", "party_of_president": "D", "lean": "liberal"}, {"name": "Ruth Bader Ginsburg", "appointed_by": "Clinton", "party_of_president": "D", "lean": "liberal"}, {"name": "Sonia Sotomayor", "appointed_by": "Obama", "party_of_president": "D", "lean": "liberal"}, {"name": "Elena Kagan", "appointed_by": "Obama", "party_of_president": "D", "lean": "liberal"}], "lean_breakdown": {"conservative": 5, "liberal": 4}, "impact_summary": "Gave corporations a powerful tool to shut down class-action lawsuits, affecting over 32 million consumers per year and blocking billions in potential settlements.", "impact_numbers": [{"metric": "Consumers affected annually by forced arbitration", "value": "32 million consumers per year blocked from joining class actions", "source_url": "https://files.consumerfinance.gov/f/201503_cfpb_arbitration-study-report-to-congress-2015.pdf", "source_name": "CFPB Arbitration Study 2015"}, {"metric": "Class-action settlements blocked over 5 years", "value": "Approximately $2.7 billion in settlements involving 160 million class members", "source_url": "https://files.consumerfinance.gov/f/201503_cfpb_arbitration-study-report-to-congress-2015.pdf", "source_name": "CFPB Arbitration Study 2015"}], "demographics_hit": ["All consumers", "Low-income communities"], "impact_on_you": "Buried in the fine print of nearly every contract you sign \u2014 your phone, your credit card, your job \u2014 is likely a clause that blocks you from suing with others, so even if a company cheats millions of people for small amounts, nobody can fight back together.", "category": "Labor, Consumer & Corporate Power", "tags": ["forced arbitration", "class actions", "consumer rights"], "constitutional_question": "Does the Federal Arbitration Act override state laws that say companies cannot use consumer contracts to ban class-action lawsuits?", "key_dissent_quote": "The Court today holds that the Federal Arbitration Act preempts a state law that was meant to ensure that large companies cannot simply 'game the system' by using their superior bargaining power to strip consumers of meaningful legal remedies.", "sources": [{"url": "https://www.oyez.org/cases/2010/09-893", "title": "Oyez: AT&T Mobility v. Concepcion", "excerpt": "5-4 decision, Scalia authored; argued Nov 2010, decided Apr 2011", "tier": "A"}, {"url": "https://files.consumerfinance.gov/f/201503_cfpb_arbitration-study-report-to-congress-2015.pdf", "title": "CFPB Arbitration Study 2015", "excerpt": "32M consumers/year; $2.7B settlements over 5 years", "tier": "A"}]}, {"id": "scotus-013", "case_name": "Epic Systems Corp. v. Lewis", "docket": "16-285", "year": 2018, "argued": "2017-10-02", "decided": "2018-05-21", "holding_summary": "Employers can require workers to sign away their right to join together in class-action lawsuits, forcing each employee to fight workplace violations alone in private arbitration.", "majority_author": {"name": "Neil Gorsuch", "appointed_by": "Trump", "party_of_president": "R"}, "vote": {"yes": 5, "no": 4}, "justices_for": [{"name": "Neil Gorsuch", "appointed_by": "Trump", "party_of_president": "R", "lean": "conservative"}, {"name": "John Roberts", "appointed_by": "G.W. Bush", "party_of_president": "R", "lean": "conservative"}, {"name": "Anthony Kennedy", "appointed_by": "Reagan", "party_of_president": "R", "lean": "conservative"}, {"name": "Clarence Thomas", "appointed_by": "G.H.W. Bush", "party_of_president": "R", "lean": "conservative"}, {"name": "Samuel Alito", "appointed_by": "G.W. Bush", "party_of_president": "R", "lean": "conservative"}], "justices_against": [{"name": "Ruth Bader Ginsburg", "appointed_by": "Clinton", "party_of_president": "D", "lean": "liberal"}, {"name": "Stephen Breyer", "appointed_by": "Clinton", "party_of_president": "D", "lean": "liberal"}, {"name": "Sonia Sotomayor", "appointed_by": "Obama", "party_of_president": "D", "lean": "liberal"}, {"name": "Elena Kagan", "appointed_by": "Obama", "party_of_president": "D", "lean": "liberal"}], "lean_breakdown": {"conservative": 5, "liberal": 4}, "impact_summary": "Enabled employers to block workers from joining together to fight wage theft, discrimination, and other workplace violations, affecting over 60 million workers \u2014 most of whom never file claims because the cost of fighting alone exceeds what they could recover.", "impact_numbers": [{"metric": "Private-sector workers under mandatory arbitration with class-action waivers", "value": "60.1 million workers (56.2% of nonunion private-sector workers) under mandatory arbitration; 24.7 million also waived class actions", "source_url": "https://www.epi.org/publication/the-growing-use-of-mandatory-arbitration/", "source_name": "EPI 2018 mandatory-arbitration report"}, {"metric": "Rate at which workers actually file arbitration claims", "value": "Only 1 in 10,400 covered workers files a claim under these provisions", "source_url": "https://www.epi.org/publication/the-growing-use-of-mandatory-arbitration/", "source_name": "EPI 2018 mandatory-arbitration report"}], "demographics_hit": ["Workers", "Low-income communities", "Women", "Communities of color"], "impact_on_you": "Your employer can force you to sign away your right to join with coworkers in court, even if the company stole wages from all of you \u2014 you would have to fight alone in a secret proceeding where your employer usually picks the judge.", "category": "Labor, Consumer & Corporate Power", "tags": ["forced arbitration", "workers' rights", "class actions"], "constitutional_question": "Does the Federal Arbitration Act allow employers to require workers to give up their right to bring class-action lawsuits over workplace violations?", "key_dissent_quote": "The Court today holds that employers may require their employees, as a condition of employment, to waive their right to bring joint, collective, and class claims about workplace wrongdoing. That is a devastating blow to workers' rights.", "sources": [{"url": "https://www.oyez.org/cases/2017/16-285", "title": "Oyez: Epic Systems v. Lewis", "excerpt": "5-4 decision, Gorsuch authored; argued Oct 2017, decided May 2018", "tier": "A"}, {"url": "https://www.epi.org/publication/the-growing-use-of-mandatory-arbitration/", "title": "EPI 2018 mandatory-arbitration report", "excerpt": "60.1M workers under mandatory arbitration; only 1 in 10,400 files a claim", "tier": "B"}]}, {"id": "scotus-014", "case_name": "Kelo v. City of New London", "docket": "04-108", "year": 2005, "argued": "2005-02-22", "decided": "2005-06-23", "holding_summary": "Local governments can take private property and transfer it to another private owner for economic development, because promoting economic growth counts as a 'public use' under the Fifth Amendment.", "majority_author": {"name": "John Paul Stevens", "appointed_by": "Ford", "party_of_president": "R"}, "vote": {"yes": 5, "no": 4}, "justices_for": [{"name": "John Paul Stevens", "appointed_by": "Ford", "party_of_president": "R", "lean": "liberal"}, {"name": "Anthony Kennedy", "appointed_by": "Reagan", "party_of_president": "R", "lean": "conservative"}, {"name": "David Souter", "appointed_by": "G.H.W. Bush", "party_of_president": "R", "lean": "liberal"}, {"name": "Ruth Bader Ginsburg", "appointed_by": "Clinton", "party_of_president": "D", "lean": "liberal"}, {"name": "Stephen Breyer", "appointed_by": "Clinton", "party_of_president": "D", "lean": "liberal"}], "justices_against": [{"name": "Sandra Day O'Connor", "appointed_by": "Reagan", "party_of_president": "R", "lean": "conservative"}, {"name": "William Rehnquist", "appointed_by": "Reagan", "party_of_president": "R", "lean": "conservative"}, {"name": "Antonin Scalia", "appointed_by": "Reagan", "party_of_president": "R", "lean": "conservative"}, {"name": "Clarence Thomas", "appointed_by": "G.H.W. Bush", "party_of_president": "R", "lean": "conservative"}], "lean_breakdown": {"conservative": 2, "liberal": 3}, "impact_summary": "Allowed governments to seize people's homes and businesses and hand them to private developers, sparking nationwide backlash that led 43 states to pass laws restricting this power \u2014 but the taking in New London itself produced zero development and the promised jobs never materialized.", "impact_numbers": [{"metric": "State reform laws passed after Kelo", "value": "43 states passed laws restricting eminent domain for economic development", "source_url": "https://www.lincolninst.edu/publications/working-papers/after-kelo", "source_name": "Lincoln Institute: After Kelo"}, {"metric": "Jobs promised vs delivered in New London", "value": "Pfizer closed its New London R&D facility in 2009, eliminating 1,400 jobs; the seized land sat vacant for over a decade", "source_url": "https://www.nytimes.com/2009/11/13/business/13pfizer.html", "source_name": "NYT 2009: Pfizer to Leave New London"}], "demographics_hit": ["Low-income communities", "Communities of color", "Homeowners"], "impact_on_you": "If a developer wants your home or business for a project that might generate more tax revenue, your local government can take it from you and sell it to the developer \u2014 even if the project never gets built.", "category": "Labor, Consumer & Corporate Power", "tags": ["eminent domain", "property rights", "economic development"], "constitutional_question": "Does the Fifth Amendment allow the government to take private property from one owner and give it to another private owner, on the grounds that the new use will generate more economic growth and tax revenue?", "key_dissent_quote": "Something has gone seriously awry with this Court's interpretation of the Constitution\u2026 The Court today replaces the Public Use Clause with a Public Purpose Clause, and that is a distinction without a constitutional difference.", "sources": [{"url": "https://www.oyez.org/cases/2004/04-108", "title": "Oyez: Kelo v. City of New London", "excerpt": "5-4 decision, Stevens authored; argued Feb 2005, decided Jun 2005", "tier": "A"}, {"url": "https://www.lincolninst.edu/publications/working-papers/after-kelo", "title": "Lincoln Institute: After Kelo", "excerpt": "43 states passed post-Kelo reform laws", "tier": "B"}]}, {"id": "scotus-015", "case_name": "Exxon Shipping Co. v. Baker", "docket": "07-219", "year": 2008, "argued": "2008-02-27", "decided": "2008-06-25", "holding_summary": "Under federal maritime law, punitive damages cannot be larger than the actual damages a company caused, slashing the punishment for the Exxon Valdez oil spill from $2.5 billion to $507.5 million.", "majority_author": {"name": "David Souter", "appointed_by": "G.H.W. Bush", "party_of_president": "R"}, "vote": {"yes": 5, "no": 3}, "justices_for": [{"name": "David Souter", "appointed_by": "G.H.W. Bush", "party_of_president": "R", "lean": "liberal"}, {"name": "John Roberts", "appointed_by": "G.W. Bush", "party_of_president": "R", "lean": "conservative"}, {"name": "Antonin Scalia", "appointed_by": "Reagan", "party_of_president": "R", "lean": "conservative"}, {"name": "Anthony Kennedy", "appointed_by": "Reagan", "party_of_president": "R", "lean": "conservative"}, {"name": "Clarence Thomas", "appointed_by": "G.H.W. Bush", "party_of_president": "R", "lean": "conservative"}], "justices_against": [{"name": "John Paul Stevens", "appointed_by": "Ford", "party_of_president": "R", "lean": "liberal"}, {"name": "Stephen Breyer", "appointed_by": "Clinton", "party_of_president": "D", "lean": "liberal"}, {"name": "Ruth Bader Ginsburg", "appointed_by": "Clinton", "party_of_president": "D", "lean": "liberal"}], "lean_breakdown": {"conservative": 4, "liberal": 1}, "impact_summary": "Capped punitive damages at a 1:1 ratio to actual damages, turning a $2.5 billion punishment for one of the worst environmental disasters in U.S. history into $507.5 million \u2014 about $15,000 per victim.", "impact_numbers": [{"metric": "Punitive damages cut", "value": "$2.5 billion punitive award reduced to $507.5 million (1:1 ratio cap)", "source_url": "https://www.oyez.org/cases/2007/07-219", "source_name": "Oyez: Exxon Shipping v. Baker"}, {"metric": "Compensation per claimant", "value": "Roughly $15,000 per person for 32,000 plaintiffs, while Exxon reported $40.6 billion in profit the same year", "source_url": "https://www.oyez.org/cases/2007/07-219", "source_name": "Oyez: Exxon Shipping v. Baker"}], "demographics_hit": ["Native Alaskans", "Fishermen", "Low-income communities"], "impact_on_you": "This decision means that no matter how badly a corporation harms you and your community, the penalty can never exceed the actual money you lost \u2014 so for a wealthy company, breaking the law can be cheaper than following it.", "category": "Labor, Consumer & Corporate Power", "tags": ["punitive damages", "environmental disaster", "corporate accountability"], "constitutional_question": "Under federal maritime law, can punitive damages be larger than actual damages, or is there a limit on the ratio between the two?", "key_dissent_quote": "The Court has no warrant to impose a rigid 1:1 ratio that Congress never enacted and that flies in the face of the jury's careful consideration of the evidence.", "sources": [{"url": "https://www.oyez.org/cases/2007/07-219", "title": "Oyez: Exxon Shipping v. Baker", "excerpt": "5-3 decision, Souter authored; $2.5B punitive cut to $507.5M; 32,000 plaintiffs", "tier": "A"}]}, {"id": "scotus-016", "case_name": "McCleskey v. Kemp", "docket": "84-6811", "year": 1987, "argued": "1986-10-15", "decided": "1987-04-22", "holding_summary": "Even when a detailed statistical study proves that killers of white victims are over four times more likely to receive the death penalty than killers of Black victims, that evidence is not enough to prove racial discrimination in an individual case.", "majority_author": {"name": "Lewis Powell", "appointed_by": "Nixon", "party_of_president": "R"}, "vote": {"yes": 5, "no": 4}, "justices_for": [{"name": "Lewis Powell", "appointed_by": "Nixon", "party_of_president": "R", "lean": "conservative"}, {"name": "William Rehnquist", "appointed_by": "Reagan", "party_of_president": "R", "lean": "conservative"}, {"name": "Byron White", "appointed_by": "Kennedy", "party_of_president": "D", "lean": "conservative"}, {"name": "Sandra Day O'Connor", "appointed_by": "Reagan", "party_of_president": "R", "lean": "conservative"}, {"name": "Antonin Scalia", "appointed_by": "Reagan", "party_of_president": "R", "lean": "conservative"}], "justices_against": [{"name": "William Brennan", "appointed_by": "Eisenhower", "party_of_president": "R", "lean": "liberal"}, {"name": "Thurgood Marshall", "appointed_by": "L.B. Johnson", "party_of_president": "D", "lean": "liberal"}, {"name": "Harry Blackmun", "appointed_by": "Nixon", "party_of_president": "R", "lean": "liberal"}, {"name": "John Paul Stevens", "appointed_by": "Ford", "party_of_president": "R", "lean": "liberal"}], "lean_breakdown": {"conservative": 5, "liberal": 4}, "impact_summary": "Shut the courthouse door on claims that the death penalty is applied in a racially discriminatory way, requiring proof of intentional bias in each individual case even when system-wide statistics show overwhelming racial disparities.", "impact_numbers": [{"metric": "Racial disparity in Georgia death penalty (Baldus study)", "value": "Killers of white victims were 4.3 times more likely to receive the death sentence than killers of Black victims", "source_url": "https://supreme.justia.com/cases/federal/us/481/279/", "source_name": "McCleskey v. Kemp, 481 U.S. 279 (1987) \u2014 citing the Baldus study"}, {"metric": "Executions 1977-2021", "value": "1,540 executions total; 57% of death row is white, 41% Black at yearend 2021", "source_url": "https://bjs.ojp.gov/document/cp21st.pdf", "source_name": "BJS: Capital Punishment, 2021"}], "demographics_hit": ["Communities of color", "Death row inmates"], "impact_on_you": "This decision means that even if you can prove with hard numbers that the death penalty is applied unfairly based on race, courts will not accept that as evidence of discrimination \u2014 requiring instead proof that an individual prosecutor or juror acted with racist intent.", "category": "Criminal Justice & Privacy", "tags": ["death penalty", "racial discrimination", "capital punishment"], "constitutional_question": "Does a detailed statistical study showing that race plays a major role in who gets the death penalty prove that the death penalty violates the Constitution's guarantee of equal protection?", "key_dissent_quote": "It is tempting to pretend that minorities on death row share a fate in no way connected to our own. Such an illusion is ultimately corrosive, for the reverberations of injustice are not so easily confined.", "sources": [{"url": "https://www.oyez.org/cases/1986/84-6811", "title": "Oyez: McCleskey v. Kemp", "excerpt": "5-4 decision, Powell authored; argued Oct 1986, decided Apr 1987", "tier": "A"}, {"url": "https://bjs.ojp.gov/document/cp21st.pdf", "title": "BJS: Capital Punishment, 2021", "excerpt": "1,540 executions 1977-2021; 57% white, 41% Black death row", "tier": "A"}]}, {"id": "scotus-017", "case_name": "District of Columbia v. Heller", "docket": "07-290", "year": 2008, "argued": "2008-03-18", "decided": "2008-06-26", "holding_summary": "The Second Amendment protects an individual's right to own a firearm for self-defense in the home, striking down D.C.'s ban on handgun possession.", "majority_author": {"name": "Antonin Scalia", "appointed_by": "Reagan", "party_of_president": "R"}, "vote": {"yes": 5, "no": 4}, "justices_for": [{"name": "Antonin Scalia", "appointed_by": "Reagan", "party_of_president": "R", "lean": "conservative"}, {"name": "John Roberts", "appointed_by": "G.W. Bush", "party_of_president": "R", "lean": "conservative"}, {"name": "Anthony Kennedy", "appointed_by": "Reagan", "party_of_president": "R", "lean": "conservative"}, {"name": "Clarence Thomas", "appointed_by": "G.H.W. Bush", "party_of_president": "R", "lean": "conservative"}, {"name": "Samuel Alito", "appointed_by": "G.W. Bush", "party_of_president": "R", "lean": "conservative"}], "justices_against": [{"name": "John Paul Stevens", "appointed_by": "Ford", "party_of_president": "R", "lean": "liberal"}, {"name": "David Souter", "appointed_by": "G.H.W. Bush", "party_of_president": "R", "lean": "liberal"}, {"name": "Ruth Bader Ginsburg", "appointed_by": "Clinton", "party_of_president": "D", "lean": "liberal"}, {"name": "Stephen Breyer", "appointed_by": "Clinton", "party_of_president": "D", "lean": "liberal"}], "lean_breakdown": {"conservative": 5, "liberal": 4}, "impact_summary": "Established for the first time that the Second Amendment guarantees an individual right to own guns, striking down handgun bans and reshaping the legal landscape for all gun regulations \u2014 making it much harder for cities to pass firearm restrictions.", "impact_numbers": [{"metric": "Civilian firearms in United States", "value": "Approximately 393 million civilian-owned firearms in the U.S. \u2014 more than one per person", "source_url": "https://www.smallarmssurvey.org/database/global-firearms-holdings", "source_name": "Small Arms Survey 2018"}, {"metric": "Police interactions and stops", "value": "Over 10 million arrests per year; Black drivers stopped at higher rates and searched more often in nearly every jurisdiction", "source_url": "https://openpolicing.stanford.edu/", "source_name": "Stanford Open Policing Project"}], "demographics_hit": ["All Americans", "Urban communities", "Communities of color"], "impact_on_you": "This decision changed the baseline for every gun law in the country \u2014 it means that the right to own a gun is an individual constitutional right, not just tied to serving in a militia, and any city or state trying to regulate firearms must overcome that protection.", "category": "Criminal Justice & Privacy", "tags": ["Second Amendment", "gun rights", "handgun ban"], "constitutional_question": "Does the Second Amendment protect an individual's right to own a firearm for private use, separate from serving in a state militia?", "key_dissent_quote": "Neither the text of the Amendment nor the arguments advanced by its proponents evidenced the slightest interest in limiting any legislature's authority to regulate private civilian uses of firearms.", "sources": [{"url": "https://www.oyez.org/cases/2007/07-290", "title": "Oyez: District of Columbia v. Heller", "excerpt": "5-4 decision, Scalia authored; argued Mar 2008, decided Jun 2008", "tier": "A"}]}, {"id": "scotus-018", "case_name": "Utah v. Strieff", "docket": "14-1373", "year": 2016, "argued": "2016-02-22", "decided": "2016-06-20", "holding_summary": "Even when police stop someone without any legal reason, evidence found during that illegal stop can still be used against them if the officer later discovers the person had an unpaid parking ticket or other minor warrant.", "majority_author": {"name": "Clarence Thomas", "appointed_by": "G.H.W. Bush", "party_of_president": "R"}, "vote": {"yes": 5, "no": 3}, "justices_for": [{"name": "Clarence Thomas", "appointed_by": "G.H.W. Bush", "party_of_president": "R", "lean": "conservative"}, {"name": "John Roberts", "appointed_by": "G.W. Bush", "party_of_president": "R", "lean": "conservative"}, {"name": "Anthony Kennedy", "appointed_by": "Reagan", "party_of_president": "R", "lean": "conservative"}, {"name": "Stephen Breyer", "appointed_by": "Clinton", "party_of_president": "D", "lean": "liberal"}, {"name": "Samuel Alito", "appointed_by": "G.W. Bush", "party_of_president": "R", "lean": "conservative"}], "justices_against": [{"name": "Sonia Sotomayor", "appointed_by": "Obama", "party_of_president": "D", "lean": "liberal"}, {"name": "Ruth Bader Ginsburg", "appointed_by": "Clinton", "party_of_president": "D", "lean": "liberal"}, {"name": "Elena Kagan", "appointed_by": "Obama", "party_of_president": "D", "lean": "liberal"}], "lean_breakdown": {"conservative": 5, "liberal": 2}, "impact_summary": "Created a loophole that allows police to stop anyone illegally, run their name through a database, and if any minor warrant pops up \u2014 even for an unpaid ticket \u2014 everything they find becomes usable in court, encouraging illegal stops in communities with high warrant rates.", "impact_numbers": [{"metric": "Warrant burden on disadvantaged communities", "value": "Millions of outstanding warrants exist across the U.S., disproportionately in low-income communities and communities of color", "source_url": "https://www.supremecourt.gov/opinions/15pdf/14-1373_l5gm.pdf", "source_name": "Utah v. Strieff, 579 U.S. __ (2016), Sotomayor dissenting"}, {"metric": "Exonerations since 1989", "value": "3,870 people exonerated since 1989, losing 36,226 years of their lives combined to wrongful convictions", "source_url": "https://www.law.umich.edu/special/exoneration/Pages/about.aspx", "source_name": "National Registry of Exonerations"}], "demographics_hit": ["Communities of color", "Low-income communities", "People with outstanding warrants"], "impact_on_you": "This decision means that police can stop you for no reason at all, and if they find out you have an old unpaid parking ticket, anything they discover during that illegal stop can be used against you in court.", "category": "Criminal Justice & Privacy", "tags": ["Fourth Amendment", "illegal stop", "search and seizure"], "constitutional_question": "When police illegally stop someone without reasonable suspicion, should evidence found afterward be thrown out of court even if the officer later discovered the person had an outstanding warrant?", "key_dissent_quote": "The Court today holds that the discovery of a warrant for an unpaid parking ticket will forgive a police officer's violation of your Fourth Amendment rights.", "sources": [{"url": "https://www.oyez.org/cases/2015/14-1373", "title": "Oyez: Utah v. Strieff", "excerpt": "5-3 decision, Thomas authored; argued Feb 2016, decided Jun 2016", "tier": "A"}, {"url": "https://www.law.umich.edu/special/exoneration/Pages/about.aspx", "title": "National Registry of Exonerations", "excerpt": "3,870 exonerations since 1989; 36,226 years lost", "tier": "A"}]}, {"id": "scotus-019", "case_name": "Egbert v. Boule", "docket": "21-147", "year": 2022, "argued": "2022-03-02", "decided": "2022-06-08", "holding_summary": "Federal agents who violate someone's constitutional rights cannot be sued for damages, even when there is no other way for the victim to get justice, unless the Supreme Court has already recognized the exact type of claim in a prior case.", "majority_author": {"name": "Clarence Thomas", "appointed_by": "G.H.W. Bush", "party_of_president": "R"}, "vote": {"yes": 6, "no": 3}, "justices_for": [{"name": "Clarence Thomas", "appointed_by": "G.H.W. Bush", "party_of_president": "R", "lean": "conservative"}, {"name": "John Roberts", "appointed_by": "G.W. Bush", "party_of_president": "R", "lean": "conservative"}, {"name": "Samuel Alito", "appointed_by": "G.W. Bush", "party_of_president": "R", "lean": "conservative"}, {"name": "Neil Gorsuch", "appointed_by": "Trump", "party_of_president": "R", "lean": "conservative"}, {"name": "Brett Kavanaugh", "appointed_by": "Trump", "party_of_president": "R", "lean": "conservative"}, {"name": "Amy Coney Barrett", "appointed_by": "Trump", "party_of_president": "R", "lean": "conservative"}], "justices_against": [{"name": "Sonia Sotomayor", "appointed_by": "Obama", "party_of_president": "D", "lean": "liberal"}, {"name": "Stephen Breyer", "appointed_by": "Clinton", "party_of_president": "D", "lean": "liberal"}, {"name": "Elena Kagan", "appointed_by": "Obama", "party_of_president": "D", "lean": "liberal"}], "lean_breakdown": {"conservative": 6, "liberal": 3}, "impact_summary": "Expanded the shield of immunity for federal agents, making it nearly impossible to sue federal officers who violate your rights \u2014 even when you have no other legal path to hold them accountable.", "impact_numbers": [{"metric": "Exonerations for wrongful convictions", "value": "3,870 people exonerated since 1989, with 36,226 years lost to wrongful imprisonment", "source_url": "https://www.law.umich.edu/special/exoneration/Pages/about.aspx", "source_name": "National Registry of Exonerations"}, {"metric": "Arrests per year (2019)", "value": "10,085,207 arrests nationwide", "source_url": "https://ucr.fbi.gov/crime-in-the-u.s/2019/crime-in-the-u.s.-2019/topic-pages/persons-arrested", "source_name": "FBI Uniform Crime Reporting 2019"}], "demographics_hit": ["All Americans", "Immigrants", "Border communities", "Communities of color"], "impact_on_you": "If a federal agent violates your constitutional rights \u2014 for example, by using excessive force against you without cause \u2014 this decision means you likely cannot sue them for damages, leaving you with no remedy at all.", "category": "Criminal Justice & Privacy", "tags": ["qualified immunity", "federal agents", "Bivens claims"], "constitutional_question": "Can a person sue federal law enforcement officers for violating their constitutional rights when no other legal remedy exists and Congress has not created a specific law allowing such a lawsuit?", "key_dissent_quote": "The Court goes to extraordinary lengths to avoid this result: It rewrites a legal standard it established just five years ago.", "sources": [{"url": "https://www.oyez.org/cases/2021/21-147", "title": "Oyez: Egbert v. Boule", "excerpt": "6-3 decision, Thomas authored; argued Mar 2022, decided Jun 2022", "tier": "A"}]}, {"id": "scotus-020", "case_name": "Vega v. Tekoh", "docket": "21-499", "year": 2022, "argued": "2022-04-20", "decided": "2022-06-23", "holding_summary": "A person whose Miranda rights were violated by police \u2014 for example, being interrogated without being told they have the right to remain silent \u2014 cannot sue the officer for damages under federal civil rights law.", "majority_author": {"name": "Samuel Alito", "appointed_by": "G.W. Bush", "party_of_president": "R"}, "vote": {"yes": 6, "no": 3}, "justices_for": [{"name": "Samuel Alito", "appointed_by": "G.W. Bush", "party_of_president": "R", "lean": "conservative"}, {"name": "John Roberts", "appointed_by": "G.W. Bush", "party_of_president": "R", "lean": "conservative"}, {"name": "Clarence Thomas", "appointed_by": "G.H.W. Bush", "party_of_president": "R", "lean": "conservative"}, {"name": "Neil Gorsuch", "appointed_by": "Trump", "party_of_president": "R", "lean": "conservative"}, {"name": "Brett Kavanaugh", "appointed_by": "Trump", "party_of_president": "R", "lean": "conservative"}, {"name": "Amy Coney Barrett", "appointed_by": "Trump", "party_of_president": "R", "lean": "conservative"}], "justices_against": [{"name": "Elena Kagan", "appointed_by": "Obama", "party_of_president": "D", "lean": "liberal"}, {"name": "Stephen Breyer", "appointed_by": "Clinton", "party_of_president": "D", "lean": "liberal"}, {"name": "Sonia Sotomayor", "appointed_by": "Obama", "party_of_president": "D", "lean": "liberal"}], "lean_breakdown": {"conservative": 6, "liberal": 3}, "impact_summary": "Stripped away the only practical tool victims had to hold police accountable for Miranda violations \u2014 if police interrogate you without telling you your rights, the statement can be thrown out of court, but you cannot sue the officer for violating your constitutional rights.", "impact_numbers": [{"metric": "Miranda violations and civil rights accountability", "value": "The Miranda warning has been required since 1966; this decision removed the ability to sue for damages when officers violate it", "source_url": "https://www.supremecourt.gov/opinions/21pdf/21-499_f2q3.pdf", "source_name": "Vega v. Tekoh, 597 U.S. __ (2022)"}, {"metric": "Exonerations for coerced confessions and Miranda violations", "value": "Roughly 12% of wrongful convictions involve false confessions, many tied to Miranda violations during interrogation", "source_url": "https://www.law.umich.edu/special/exoneration/Pages/about.aspx", "source_name": "National Registry of Exonerations"}], "demographics_hit": ["Communities of color", "Low-income communities", "Young people"], "impact_on_you": "If police interrogate you without telling you about your right to remain silent and your right to a lawyer, your confession might be thrown out in court \u2014 but you have no right to sue the officer for violating your rights, leaving no real consequence for the misconduct.", "category": "Criminal Justice & Privacy", "tags": ["Miranda rights", "police misconduct", "civil rights lawsuits"], "constitutional_question": "When police violate a person's Miranda rights during interrogation, can the victim sue the officer for damages under Section 1983, the federal civil rights law?", "key_dissent_quote": "Today's decision prevents individuals from obtaining any redress when police violate their rights under Miranda.", "sources": [{"url": "https://www.oyez.org/cases/2021/21-499", "title": "Oyez: Vega v. Tekoh", "excerpt": "6-3 decision, Alito authored; argued Apr 2022, decided Jun 2022", "tier": "A"}]}];
